namespace Zenix.Core.Zalo.Storage;

/// <summary>
/// Encapsulates the execution result of a non-query SQLite statement,
/// exposing the last inserted row identifier and count of affected rows.
/// </summary>
public sealed record SqliteExecutionResult
{
    /// <summary>
    /// Gets the row identifier generated by the most recently executed successful INSERT statement,
    /// or <c>0</c> if no row was inserted or if a UNIQUE constraint conflict was safely suppressed.
    /// </summary>
    public long LastInsertedId { get; init; }

    /// <summary>
    /// Gets the total number of rows modified, inserted, or deleted by the statement,
    /// or <c>0</c> if no rows were affected or on a suppressed conflict.
    /// </summary>
    public int RowsAffected { get; init; }
}
